    if (answer == 1 || answer == 2) {
        break;                       // 올바른 입력이면 탈출!
    }

    printf("⚠️ 1 또는 2만 입력해주세요. 다시!\n");
    // break 없이 계속 → 자동으로 반복문 처음으로 돌아감
}

printf("입력한 값: %d\n", answer);

return 0;
</code></pre> <p>} 실행 결과:</p> <p>선택하세요 (1 또는 2): 5 ⚠️ 1 또는 2만 입력해주세요. 다시! 선택하세요 (1 또는 2): 99 ⚠️ 1 또는 2만 입력해주세요. 다시! 선택하세요 (1 또는 2): 1 입력한 값: 1 Step 2: 똑같은 걸 do-while로 바꿔보기 Step 1과 동일한 동작을 do-while로 표현하면 이렇습니다.</p>

include  <p>int main(void) {     int answer;</p> <pre><code>do {
    printf("선택하세요 (1 또는 2): ");
    scanf("%d", &amp;answer);

    if (answer != 1 &amp;&amp; answer != 2) {
        printf("⚠️ 1 또는 2만 입력해주세요. 다시!\n");
    }

} while (answer != 1 &amp;&amp; answer != 2);  // 잘못된 입력이면 다시!

printf("입력한 값: %d\n", answer);

return 0;
</code></pre> <p>} 💡 두 코드의 동작은 완전히 같습니다. do-while은 "올바른 입력이 들어올 때까지 반복한다"는 의도가 더 잘 보이는 장점이 있습니다.</p> <p>Step 3: MBTI 게임에 유효성 검사 추가하기 지금까지 배운 반복문에 유효성 검사를 넣어서 게임을 완성해봅시다.</p>

include  <p>int main(void) {</p> <pre><code>// 점수와 질문 번호를 저장할 변수
int score = 0;
int answer;
int i;

// 4개의 질문을 순서대로 진행
for (i = 1; i &lt;= 4; i++) {

    // 질문 출력
    if (i == 1) printf("\nQ%d. 혼자 있는 시간이 편하다\n", i);
    else if (i == 2) printf("\nQ%d. 계획 없이 여행을 떠날 수 있다\n", i);
    else if (i == 3) printf("\nQ%d. 논리가 감정보다 중요하다\n", i);
    else if (i == 4) printf("\nQ%d. 마감 직전에 집중력이 올라간다\n", i);

    // 🔒 유효성 검사: 1 또는 2가 입력될 때까지 반복
    do {
        printf("  👉 그렇다(1) / 아니다(2): ");
        scanf("%d", &amp;answer);

        if (answer != 1 &amp;&amp; answer != 2) {
            printf("  ⚠️ 1 또는 2만 입력해주세요!\n");
        }

    } while (answer != 1 &amp;&amp; answer != 2);

    // 점수 계산
    if (answer == 1) {
        score++;
    }
}

printf("\n✨ 완료! 총 점수: %d / 4\n", score);

return 0;
</code></pre> <p>} 실행 결과:</p> <p>Q1. 혼자 있는 시간이 편하다   👉 그렇다(1) / 아니다(2): 3   ⚠️ 1 또는 2만 입력해주세요!   👉 그렇다(1) / 아니다(2): 1</p> <p>Q2. 계획 없이 여행을 떠날 수 있다   👉 그렇다(1) / 아니다(2): 2</p> <p>Q3. 논리가 감정보다 중요하다   👉 그렇다(1) / 아니다(2): 1</p> <p>Q4. 마감 직전에 집중력이 올라간다   👉 그렇다(1) / 아니다(2): 2</p> <p>✨ 완료! 총 점수: 2 / 4 📝 전체 코드</p>

include  <p>int main(void) {</p> <pre><code>int score = 0;
int answer;
int i;

for (i = 1; i &lt;= 4; i++) {

    if (i == 1) printf("\nQ%d. 혼자 있는 시간이 편하다\n", i);
    else if (i == 2) printf("\nQ%d. 계획 없이 여행을 떠날 수 있다\n", i);
    else if (i == 3) printf("\nQ%d. 논리가 감정보다 중요하다\n", i);
    else if (i == 4) printf("\nQ%d. 마감 직전에 집중력이 올라간다\n", i);

    do {
        printf("  👉 그렇다(1) / 아니다(2): ");
        scanf("%d", &amp;answer);

        if (answer != 1 &amp;&amp; answer != 2) {
            printf("  ⚠️ 1 또는 2만 입력해주세요!\n");
        }

    } while (answer != 1 &amp;&amp; answer != 2);

    if (answer == 1) {
        score++;
    }
}

printf("\n✨ 완료! 총 점수: %d / 4\n", score);

return 0;
</code></pre> <p>} ⚠️ 주의할 점 do-while 끝에 세미콜론(;) 필수!</p> <p>} while (조건);  // ← 이거 빠뜨리면 컴파일 에러! while (1)은 반드시 break와 짝꿍! break 없이 while (1)을 쓰면 프로그램이 영원히 끝나지 않습니다. 실수로 빠졌다면 Ctrl + C로 탈출하세요.</p> <p>do-while vs while (1) + break 언제 쓰나요?</p> <p>상황  추천 "최소 1회 실행" 의도를 명확히 표현하고 싶을 때    do-while 탈출 조건이 복잡하거나 여러 곳에 있을 때 while (1) + break ✅ 점검하기 1. while문과 do-while문의 가장 큰 차이는 무엇인가요?</p> <p>while문은 조건이 처음부터 거짓이면 한 번도 실행되지 않지만, do-while문은 조건과 상관없이 무조건 최소 1번은 실행됩니다.</p> <ol> <li>아래 코드에서 빠진 것은 무엇인가요?</li> </ol> <p>do {     printf("숫자를 입력하세요: ");     scanf("%d", &amp;num); } while (num &lt; 0) while (num &lt; 0) 뒤에 세미콜론(;) 이 빠져 있습니다.</p> <ol> <li>while (1) + break 패턴에서 break를 쓰지 않으면 어떻게 되나요?</li> </ol> <p>조건이 항상 참(1)이기 때문에 반복문이 영원히 끝나지 않는 무한루프에 빠집니다.</p>

include  <p>/ ---- 프로토타입 선언 ---- / int add(int a, int b); int subtract(int a, int b); void printResult(int result);</p> <p>/ ---- main 함수 ---- / int main(void) {     int x = 20, y = 8;</p> <pre><code>int sum  = add(x, y);       // 덧셈
int diff = subtract(x, y);  // 뺄셈

printf("덧셈 결과: ");
printResult(sum);

printf("뺄셈 결과: ");
printResult(diff);

return 0;
</code></pre> <p>}</p> <p>/ ---- 함수 정의 (main 아래) ---- / int add(int a, int b) {     int result = a + b;   // 이 result는 add의 지역변수     return result; }                         // 함수 끝 → result 사라짐 💨</p> <p>int subtract(int a, int b) {     int result = a - b;   // 이 result는 subtract의 지역변수     return result; }                         // 함수 끝 → result 사라짐 💨</p> <p>void printResult(int result) {     printf("%d\n", result); } 실행 결과:</p> <p>덧셈 결과: 28 뺄셈 결과: 12 💡 add, subtract, printResult 모두 result라는 변수명을 써도 각자의 방에 있으므로 충돌 없음! 🎉</p> <p>⚠️ 주의할 점 실수  이유  해결 프로토타입에 ; 빠뜨리기   int add(int a, int b) 는 함수 정의로 오해됨  끝에 반드시 ; 붙이기 지역변수를 다른 함수에서 쓰려 함  다른 방의 변수는 보이지 않음    매개변수나 반환값으로 전달 프로토타입과 정의의 시그니처 불일치 컴파일 오류 발생   자료형·매개변수 개수 맞추기 ✅ 점검하기 1. 프로토타입 선언이 필요한 이유는 무엇인가요?</p> 정답 확인 C 언어는 코드를 위에서 아래로 읽기 때문에, main보다 뒤에 정의된 함수를 미리 컴파일러에게 알려줘야 호출할 수 있습니다.  <ol> <li>아래 코드의 실행 결과는 무엇인가요?</li> </ol> <p>void test(void) { int n = 50; printf("%d\n", n); } int main(void) { int n = 10; test(); printf("%d\n", n); return 0; }</p> 정답 확인 50 10 test의 n과 main의 n은 서로 다른 지역변수입니다.   <ol> <li>함수가 끝난 뒤 그 안의 지역변수는 어떻게 되나요?</li> </ol> 정답 확인 함수 실행이 끝나면 지역변수는 메모리에서 사라집니다. 다음에 함수가 다시 호출되면 새로 만들어집니다.  <p>🔗 다음 장 미리보기 다음 장에서는 배열 (1) — 같은 자료형 묶어서 관리하기를 배웁니다. 점수 10개를 변수 10개로 관리하는 번거로움을 한 번에 해결해볼게요! 📦</p>
